export const machines=[{name:'半自動溶接機',price:450000,capacity:18,quality:70,failure:.006,maintenance:5000,types:['鉄骨','製缶']},{name:'TIG精密溶接機',price:900000,capacity:15,quality:90,failure:.004,maintenance:8000,types:['精密','製缶']},{name:'溶接ロボット',price:2400000,capacity:42,quality:95,failure:.003,maintenance:16000,types:['鉄骨','製缶','大型']}];
export const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
export function initial(){return {version:1,day:1,cash:2200000,debt:0,rep:35,satisfaction:70,level:1,research:0,condition:'標準',workers:[{id:1,name:'佐藤 健太',skill:62,salary:240000,morale:80,fatigue:0,cert:0,training:0},{id:2,name:'田中 美咲',skill:48,salary:210000,morale:80,fatigue:0,cert:0,training:0}],equipment:[{id:1,type:0,health:100,broken:false,busyDays:0}],jobs:[],offers:[],candidates:[],ledger:[],history:[],logs:[{day:1,text:'小さな町工場から、日本を代表する溶接企業へ。まずは受注市場で仕事を選びましょう。'}],monthRevenue:0,monthExpense:0,totalProfit:0,delivered:0,stock:0,nextId:10,bankrupt:false,won:false};}
export function log(s,text){s.logs.unshift({day:s.day,text});s.logs=s.logs.slice(0,60);}
export function money(s,amount,category,profit=true){s.cash+=amount;s.ledger.unshift({day:s.day,amount,category});s.ledger=s.ledger.slice(0,200);if(profit){if(amount>0)s.monthRevenue+=amount;else s.monthExpense-=amount;}}
export function spend(s,amount,category){if(s.bankrupt)throw Error('倒産した会社では操作できません。');if(s.cash<amount)throw Error('資金が足りません。');money(s,-amount,category);}
export function offers(s){let names=['東和建設','みなと製作所','中央プラント','日本産機'];let types=['鉄骨','製缶','精密','大型'];s.offers=Array.from({length:6},(_,i)=>{let tier=i<2?0:i<4?1:2;let type=types[(i+Math.floor(s.day/7))%4];if(i===0)type='鉄骨';let work=45+tier*55+i*8;return {id:s.nextId++,client:names[i%4],name:({鉄骨:'建築用スチールフレーム',製缶:'産業用タンク',精密:'ステンレス精密配管',大型:'大型プラント架台'})[type],type,work,reward:Math.round((work*4800+tier*100000)*(1+s.rep/500)),material:8+tier*9+i,required:52+tier*12,cert:type==='大型'?1:0,minRep:tier*20,days:8+tier*4,contract:i===5,repeat:0};});}
export function estimate(s,j,workerId,machineId,grade=1,mode='標準'){let w=s.workers.find(x=>x.id===Number(workerId)),m=s.equipment.find(x=>x.id===Number(machineId));if(!w||!m)return {quality:0,speed:0};let e=machines[m.type];let quality=clamp(w.skill*.45+e.quality*.3+m.health*.1+grade*4+w.cert*3+s.research*2+(s.level-1)*1.5-(w.fatigue*.12)+(mode==='丁寧'?8:mode==='急行'?-10:0));let speed=e.capacity*(.5+w.skill/100)*(mode==='丁寧'?.75:mode==='急行'?1.35:1)*(1-w.fatigue/250);return {quality:Math.round(quality),speed};}
export function accept(s,id){let j=s.offers.find(x=>x.id===id);if(!j)throw Error('案件が見つかりません。');if(s.jobs.length>=s.level+2)throw Error('同時受注枠がいっぱいです。');if(s.rep<j.minRep)throw Error('会社の評判が不足しています。');if(j.cert&&!s.workers.some(w=>w.cert>=j.cert))throw Error('有資格者が必要です。');s.jobs.push({...j,deadline:s.day+j.days,progress:0,status:'準備',grade:1,mode:'標準',qualitySum:0,workSum:0,reworked:false});s.offers=s.offers.filter(x=>x.id!==id);log(s,`${j.client}の「${j.name}」を受注。`);}
export function start(s,id,workerId,machineId,grade,mode){let j=s.jobs.find(x=>x.id===id),w=s.workers.find(x=>x.id===Number(workerId)),m=s.equipment.find(x=>x.id===Number(machineId));if(!j||j.status!=='準備')throw Error('準備中の案件を選択してください。');if(!w||!m||m.broken||w.training)throw Error('稼働できる従業員・設備を選択してください。');if(!machines[m.type].types.includes(j.type))throw Error('この設備は案件の工法に対応していません。');if(w.cert<j.cert)throw Error('担当者の資格が不足しています。');if(s.jobs.some(x=>x.status==='生産中'&&(x.workerId===w.id||x.machineId===m.id)))throw Error('担当者または設備が他の案件で稼働中です。');if(![1,2,3].includes(grade)||!['標準','丁寧','急行'].includes(mode))throw Error('無効な作業条件です。');let used=Math.min(s.stock,j.material);spend(s,(j.material-used)*6000+(grade-1)*j.material*1800,'材料費');s.stock-=used;Object.assign(j,{workerId:w.id,machineId:m.id,grade,mode,status:'生産中'});}
export function inspect(s,id){let j=s.jobs.find(x=>x.id===id);if(j?.status!=='検査待ち')throw Error('生産完了後に検査できます。');j.quality=Math.round(j.qualitySum/Math.max(1,j.workSum));j.status='納品待ち';log(s,`検査結果：品質 ${j.quality} / 要求 ${j.required}。`);}
export function rework(s,id){let j=s.jobs.find(x=>x.id===id);if(j?.status!=='納品待ち'||j.reworked)throw Error('再加工は検査後に一度だけ可能です。');let w=s.workers.find(x=>x.id===j.workerId),m=s.equipment.find(x=>x.id===j.machineId);if(!w||!m||m.broken||w.training||s.jobs.some(x=>x.id!==id&&x.status==='生産中'&&(x.workerId===w.id||x.machineId===m.id)))throw Error('元の担当者と設備が作業可能になるまでお待ちください。');spend(s,j.material*2500,'再加工費');j.reworked=true;j.status='生産中';j.progress=j.work*.7;j.mode='丁寧';j.qualitySum=0;j.workSum=0;}
export function deliver(s,id,rng=Math.random){let j=s.jobs.find(x=>x.id===id);if(j?.status!=='納品待ち')throw Error('検査が必要です。');let late=Math.max(0,s.day-j.deadline),gap=j.quality-j.required;let factor=clamp(1+gap*.008-late*.045,.2,1.2);let reward=Math.round(j.reward*factor);money(s,reward,j.contract?'長期契約収入':j.repeat?'継続取引収入':j.type==='大型'?'大型案件報酬':j.type==='精密'?'溶接加工費':'製品製造代金');if(gap<0)money(s,-Math.round(j.reward*Math.min(.3,-gap*.008)),'不良品補償損失');s.rep=clamp(s.rep+(gap>=0?3:-6)-late);s.satisfaction=clamp(s.satisfaction+(gap>=0?4:-10)-late*2);s.delivered++;s.jobs=s.jobs.filter(x=>x.id!==id);log(s,`${j.name}を納品。入金 ¥${reward.toLocaleString()}${late?`（${late}日遅延）`:''}。`);if((j.contract&&j.repeat<2)||(s.satisfaction>=80&&rng()<clamp((s.satisfaction-50)/100+s.rep/250,0,.95))){s.offers.push({...j,id:s.nextId++,reward:Math.round(j.reward*1.05),repeat:j.repeat+1});log(s,`${j.client}から継続案件が届きました。`);}}
export function advance(s,rng=Math.random){if(s.bankrupt)return;s.day++;let activeWorkers=new Set();for(let j of s.jobs.filter(x=>x.status==='生産中')){let w=s.workers.find(x=>x.id===j.workerId),m=s.equipment.find(x=>x.id===j.machineId);if(!w||!m||m.broken||w.training)continue;let spec=machines[m.type];if(rng()<spec.failure+(100-m.health)*.0005){m.broken=true;log(s,`${spec.name}が故障。修理が必要です。`);continue;}let {quality,speed}=estimate(s,j,w.id,m.id,j.grade,j.mode);let work=Math.min(speed,j.work-j.progress);j.progress+=work;j.qualitySum+=quality*work;j.workSum+=work;w.fatigue=clamp(w.fatigue+(j.mode==='急行'?12:6));w.skill=clamp(w.skill+.15);m.health=clamp(m.health-.9);m.busyDays++;activeWorkers.add(w.id);money(s,-Math.round(900+speed*60),'電気代');if(j.progress>=j.work-.001){j.status='検査待ち';log(s,`${j.name}の製造が完了しました。品質検査へ進んでください。`);}}
for(let w of [...s.workers]){if(!activeWorkers.has(w.id))w.fatigue=clamp(w.fatigue-12);if(w.training){w.training--;if(!w.training){if(w.course==='資格'){w.cert=Math.min(2,w.cert+1);}else w.skill=clamp(w.skill+12);log(s,`${w.name}が${w.course}を修了しました。`);}}if(s.day%30===0){w.morale=clamp(w.morale+(w.salary>=180000+w.skill*800?3:-12));if(w.morale<25&&!s.jobs.some(j=>j.workerId===w.id)){s.workers=s.workers.filter(x=>x.id!==w.id);log(s,`${w.name}が待遇への不満から退職しました。`);}}}
if(s.day%7===1)offers(s);
if(s.day%30===0){money(s,-s.workers.reduce((a,w)=>a+w.salary,0),'給与');money(s,-(90000+s.level*30000),'工場賃料');money(s,-s.equipment.reduce((a,m)=>a+machines[m.type].maintenance,0),'定期保守費');if(s.debt){money(s,-Math.round(s.debt*.045/12),'借入利息');let p=Math.min(s.debt,50000);money(s,-p,'元金返済',false);s.debt-=p;}let profit=s.monthRevenue-s.monthExpense;if(profit>0)money(s,-Math.round(profit*.2),'税金');let net=s.monthRevenue-s.monthExpense;s.totalProfit+=net;s.history.push({day:s.day,revenue:s.monthRevenue,expense:s.monthExpense,profit:net,cash:s.cash});log(s,`月次決算：税引後利益 ¥${Math.round(net).toLocaleString()}。`);s.monthRevenue=0;s.monthExpense=0;}
if(s.cash<0){s.bankrupt=true;log(s,'現預金が不足し支払不能となりました。会社は倒産しました。');}if(!s.won&&s.rep>=90&&s.totalProfit>=10000000&&s.level>=3){s.won=true;log(s,'日本を代表する溶接企業に成長しました！自由経営は続けられます。');}}
export function action(s,type,id,value){if(s.bankrupt)throw Error('倒産した会社では操作できません。');let w=s.workers.find(x=>x.id===id),m=s.equipment.find(x=>x.id===id);if(type==='buy'){if(s.equipment.length>=s.level*2)throw Error('工場を増築して設備枠を増やしてください。');spend(s,machines[id].price,'設備購入費');s.equipment.push({id:s.nextId++,type:id,health:100,broken:false,busyDays:0});}if(type==='maintain'){spend(s,m.broken?80000:20000,m.broken?'設備修理費':'設備整備費');m.health=100;m.broken=false;}if(type==='expand'){spend(s,s.level*1000000,'工場増築費');s.level++;}if(type==='research'){if(s.research>=10)throw Error('研究は最大レベルです。');spend(s,200000*(s.research+1),'研究開発費');s.research++;}if(type==='stock'){spend(s,60000,'材料費');s.stock+=10;}if(type==='recruit'){if(s.candidates.length)throw Error('募集中の候補者がいます。');spend(s,30000,'求人広告費');s.candidates=[{id:s.nextId++,name:'鈴木 悠太',skill:40+(s.day%20),salary:220000,morale:80,fatigue:0,cert:0,training:0},{id:s.nextId++,name:'高橋 匠',skill:78,salary:310000,morale:80,fatigue:0,cert:1,training:0}];}if(type==='hire'){let c=s.candidates.find(x=>x.id===id);if(!c)throw Error('候補者が見つかりません。');if(s.workers.length>=s.level*4)throw Error('人員枠がいっぱいです。');s.workers.push({...c});s.candidates=s.candidates.filter(x=>x.id!==id);log(s,`${c.name}を採用しました。`);}if(type==='train'||type==='cert'){if(w.training||s.jobs.some(j=>j.workerId===id&&j.status==='生産中'))throw Error('稼働中・研修中は受講できません。');if(type==='cert'&&w.cert>=2)throw Error('最上位資格を取得済みです。');spend(s,type==='cert'?120000:60000,'研修費');w.training=type==='cert'?5:3;w.course=type==='cert'?'資格':'技術研修';}if(type==='salary'){if(!Number.isFinite(value)||value<180000||value>1000000)throw Error('月給は18万〜100万円で指定してください。');if(value>w.salary)w.morale=clamp(w.morale+10);if(value<w.salary)w.morale=clamp(w.morale-15);w.salary=Math.round(value);}if(type==='bonus'){spend(s,50000,'賞与');w.morale=clamp(w.morale+20);}if(type==='loan'){if(s.debt+500000>1000000+s.rep*20000)throw Error('融資限度額を超えています。');s.debt+=500000;money(s,500000,'銀行融資',false);}if(type==='repay'){let n=Math.min(s.debt,500000);if(s.cash<n)throw Error('資金が足りません。');money(s,-n,'任意元金返済',false);s.debt-=n;}}
